-- در Supabase > SQL Editor اجرا کنید.
create table if not exists public.products (
 id bigint generated by default as identity primary key,
 category_id text not null check(category_id in ('breakfast','sandwich','appetizer','cafe','drinks')),
 name text not null, description text default '', price bigint,
 active boolean not null default true, sort_order integer not null default 0,
 created_at timestamptz not null default now()
);
alter table public.products enable row level security;
drop policy if exists "Public read active products" on public.products;
create policy "Public read active products" on public.products for select using(active=true or auth.uid() is not null);
drop policy if exists "Authenticated update products" on public.products;
create policy "Authenticated update products" on public.products for update to authenticated using(auth.uid() is not null) with check(auth.uid() is not null);
